{"filePath": "/Users/rithviknishad/ohc.network/care/care/abdm/service/errors.py", "content": "import json
import logging

logger = logging.getLogger(__name__)

NON_FIELD_KEYS = {"timestamp", "path", "requestId", "status"}


class AbdmError(Exception):
    """A refusal from an ABDM service, or a failure to reach one."""

    def __init__(
        self,
        status: int,
        code: str | None,
        message: str,
        request_id: str,
        fields: dict | None = None,
    ):
        super().__init__(message)
        self.status = status
        self.code = code
        self.message = message
        self.request_id = request_id
        self.fields = fields or {}

    def has_code(self, code: str) -> bool:
        # Codes arrive bare ("ABDM-1114") or with a trailing ": " separator.
        return bool(self.code) and self.code.split(":")[0].strip() == code

    @classmethod
    def from_response(cls, response, request_id: str) -> "AbdmError":
        body = None
        if response.content:
            try:
                body = response.json()
            except (ValueError, json.JSONDecodeError):
                body = None
        logger.warning(
            "ABDM refused REQUEST-ID=%s status=%s body=%s",
            request_id,
            response.status_code,
            body if body is not None else response.text[:500],
        )

        code, message, fields = None, "", {}
        if isinstance(body, dict):
            # Error shapes vary by endpoint: {"error": {...}}, {"code": ...},
            # {"value": {...}} and {"<field>": "<message>", "timestamp": ...}.
            nested = body.get("error") if isinstance(body.get("error"), dict) else None
            nested = nested or (
                body.get("value") if isinstance(body.get("value"), dict) else None
            )
            source = nested or body
            code = source.get("code")
            message = (
                source.get("message")
                or source.get("description")
                or (body.get("error") if isinstance(body.get("error"), str) else "")
                or ""
            )
            if not nested and not code:
                fields = {
                    key: value
                    for key, value in body.items()
                    if key not in NON_FIELD_KEYS and isinstance(value, str)
                }
                if fields and not message:
                    message = "; ".join(f"{k}: {v}" for k, v in fields.items())
        return cls(
            status=response.status_code,
            code=str(code).strip() if code is not None else None,
            message=message or f"ABDM returned HTTP {response.status_code}",
            request_id=request_id,
            fields=fields,
        )
"}

{"filePath": "/Users/rithviknishad/ohc.network/care/care/abdm/service/crypto.py", "content": "import base64

from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.asymmetric import padding
from cryptography.hazmat.primitives.serialization import (
    load_der_public_key,
    load_pem_public_key,
)

# Keyed by the `encryptionAlgorithm` an ABDM certificate endpoint publishes.
PADDINGS = {
    "RSA/ECB/OAEPWithSHA-1AndMGF1Padding": lambda: padding.OAEP(
        mgf=padding.MGF1(algorithm=hashes.SHA1()),  # noqa: S303
        algorithm=hashes.SHA1(),  # noqa: S303
        label=None,
    ),
    "RSA/ECB/PKCS1Padding": padding.PKCS1v15,
}


class UnsupportedEncryptionAlgorithmError(Exception):
    pass


def load_public_key(public_key: str):
    if public_key.lstrip().startswith("-----BEGIN"):
        return load_pem_public_key(public_key.encode())
    return load_der_public_key(base64.b64decode(public_key))


def encrypt(value: str, public_key: str, algorithm: str) -> str:
    """RSA-encrypt `value` with the algorithm the certificate names.

    Refuses an algorithm it does not recognise rather than guessing a default.
    """
    if algorithm not in PADDINGS:
        raise UnsupportedEncryptionAlgorithmError(algorithm)
    key = load_public_key(public_key)
    return base64.b64encode(key.encrypt(value.encode(), PADDINGS[algorithm]())).decode()
"}

{"content": """"Every ABHA (M1) call Care makes, one function per operation.

Callers pass plaintext; this module encrypts what ABDM requires encrypted
(Aadhaar, mobile, ABHA number, OTP, search index) before it leaves the process.
"""

from django.conf import settings
from django.core.cache import cache

from care.abdm.service import crypto, gateway
from care.abdm.service.client import abdm_request
from care.abdm.service.errors import AbdmError

CERTIFICATE_CACHE_KEY = "abdm:abha:certificate"
ENROLMENT_CONSENT = {"code": "abha-enrollment", "version": "1.4"}
# Codes that mean the gateway token itself was refused.
GATEWAY_AUTH_FAILURES = {"900900", "900901", "900902"}


def _url(path: str) -> str:
    return f"{settings.ABDM_ABHA_URL}{path}"


def _call(method, path, *, json=None, x_token=None, t_token=None, headers=None, raw=False):
    request_headers = {"Authorization": f"Bearer {gateway.get_access_token()}"}
    if x_token:
        request_headers["X-token"] = f"Bearer {x_token}"
    if t_token:
        request_headers["T-token"] = f"Bearer {t_token}"
    request_headers.update(headers or {})
    try:
        return abdm_request(method, _url(path), json=json, headers=request_headers, raw=raw)
    except AbdmError as e:
        if any(e.has_code(code) for code in GATEWAY_AUTH_FAILURES):
            # Drop the cached token so the next call fetches a fresh one; never retry here.
            gateway.invalidate_access_token()
        raise


def get_certificate() -> dict:
    if certificate := cache.get(CERTIFICATE_CACHE_KEY):
        return certificate
    certificate = _call("GET", "/v3/profile/public/certificate")
    cache.set(
        CERTIFICATE_CACHE_KEY, certificate, timeout=settings.ABDM_CERTIFICATE_CACHE_SECONDS
    )
    return certificate


def encrypt(value: str) -> str:
    certificate = get_certificate()
    return crypto.encrypt(
        value, certificate["publicKey"], certificate["encryptionAlgorithm"]
    )


def _otp_auth(txn_id: str, otp: str) -> dict:
    return {
        "authMethods": ["otp"],
        "otp": {"txnId": txn_id, "otpValue": encrypt(otp)},
    }


# Login (profile/login family)


def login_request_otp(*, scope, login_hint, login_id, otp_system, txn_id=None):
    body = {
        "scope": scope,
        "loginHint": login_hint,
        "loginId": encrypt(login_id),
        "otpSystem": otp_system,
    }
    if txn_id:
        body["txnId"] = txn_id
    return _call("POST", "/v3/profile/login/request/otp", json=body)


def login_verify_otp(*, scope, txn_id, otp):
    return _call(
        "POST",
        "/v3/profile/login/verify",
        json={"scope": scope, "authData": _otp_auth(txn_id, otp)},
    )


def login_verify_user(*, abha_number, txn_id, t_token):
    return _call(
        "POST",
        "/v3/profile/login/verify/user",
        json={"ABHANumber": abha_number, "txnId": txn_id},
        t_token=t_token,
    )


def search_by_mobile(mobile: str):
    return _call(
        "POST",
        "/v3/profile/account/abha/search",
        json={"scope": ["search-abha"], "mobile": encrypt(mobile)},
    )


# Enrolment


def enrol_request_otp(*, aadhaar, txn_id=None):
    body = {
        "scope": ["abha-enrol"],
        "loginHint": "aadhaar",
        "loginId": encrypt(aadhaar),
        "otpSystem": "aadhaar",
    }
    if txn_id:
        body["txnId"] = txn_id
    return _call("POST", "/v3/enrollment/request/otp", json=body)


def enrol_by_aadhaar_otp(*, txn_id, otp, mobile=None):
    auth = _otp_auth(txn_id, otp)
    if mobile:
        # Sent plain: the specification types this field as a plain 10 digit number.
        auth["otp"]["mobile"] = mobile
    return _call(
        "POST",
        "/v3/enrollment/enrol/byAadhaar",
        json={"authData": auth, "consent": ENROLMENT_CONSENT},
    )


def enrol_by_demographics(
    *, aadhaar, name, date_of_birth, gender, state_code, district_code, mobile=None,
    pincode=None, address=None,
):
    demo_auth = {
        "aadhaarNumber": encrypt(aadhaar),
        "name": name,
        "dateOfBirth": date_of_birth,
        "gender": gender,
        "stateCode": state_code,
        "districtCode": district_code,
    }
    optional = {"mobile": mobile, "pinCode": pincode, "address": address}
    demo_auth.update({k: v for k, v in optional.items() if v})
    return _call(
        "POST",
        "/v3/enrollment/enrol/byAadhaar",
        json={
            "authData": {"authMethods": ["demo_auth"], "demo_auth": demo_auth},
            "consent": ENROLMENT_CONSENT,
        },
        headers={"BENEFIT_NAME": settings.ABDM_BENEFIT_NAME},
    )


def enrol_request_mobile_otp(*, txn_id, mobile):
    return _call(
        "POST",
        "/v3/enrollment/request/otp",
        json={
            "txnId": txn_id,
            "scope": ["abha-enrol", "mobile-verify"],
            "loginHint": "mobile",
            "loginId": encrypt(mobile),
            "otpSystem": "abdm",
        },
    )


def enrol_verify_mobile_otp(*, txn_id, otp):
    return _call(
        "POST",
        "/v3/enrollment/auth/byAbdm",
        json={"scope": ["abha-enrol", "mobile-verify"], "authData": _otp_auth(txn_id, otp)},
    )


def address_suggestions(*, txn_id):
    return _call(
        "GET",
        "/v3/enrollment/enrol/suggestion",
        headers={"TRANSACTION_ID": txn_id},
    )


def create_address(*, txn_id, address):
    return _call(
        "POST",
        "/v3/enrollment/enrol/abha-address",
        json={"txnId": txn_id, "abhaAddress": address, "preferred": 1},
    )


# Profile (needs the user X-token)


def get_profile(*, x_token):
    return _call("GET", "/v3/profile/account", x_token=x_token)


def get_card(*, x_token):
    return _call("GET", "/v3/profile/account/abha-card", x_token=x_token, raw=True)


def get_qr_code(*, x_token):
    return _call("GET", "/v3/profile/account/qrCode", x_token=x_token, raw=True)


def profile_request_mobile_otp(*, x_token, mobile):
    return _call(
        "POST",
        "/v3/profile/account/request/otp",
        json={
            "scope": ["abha-profile", "mobile-verify"],
            "loginHint": "mobile",
            "loginId": encrypt(mobile),
            "otpSystem": "abdm",
        },
        x_token=x_token,
    )


def profile_verify_mobile_otp(*, x_token, txn_id, otp):
    return _call(
        "POST",
        "/v3/profile/account/verify",
        json={"scope": ["abha-profile", "mobile-verify"], "authData": _otp_auth(txn_id, otp)},
        x_token=x_token,
    )
