{"content": """"Server-side state for one patient's ABHA journey at the desk.

The browser only ever holds the flow id. Transaction ids, ABDM user tokens and
encrypted identifiers stay here, scoped to the user who started the flow.
"""

import uuid
from dataclasses import asdict, dataclass, field

from django.core.cache import cache
from rest_framework.exceptions import ValidationError

FLOW_TTL_SECONDS = 30 * 60


@dataclass
class AbhaFlow:
    id: str
    user_id: int
    txn_id: str | None = None
    verify_scope: list[str] = field(default_factory=list)
    t_token: str | None = None
    x_token: str | None = None
    mobile: str | None = None
    has_aadhaar: bool = False
    search_results: list[dict] = field(default_factory=list)
    accounts: list[dict] = field(default_factory=list)
    profile: dict | None = None

    @staticmethod
    def _key(flow_id: str) -> str:
        return f"abdm:abha-flow:{flow_id}"

    @classmethod
    def start(cls, user) -> "AbhaFlow":
        return cls(id=str(uuid.uuid4()), user_id=user.id)

    @classmethod
    def load(cls, flow_id, user) -> "AbhaFlow":
        data = cache.get(cls._key(str(flow_id)))
        if not data or data["user_id"] != user.id:
            raise ValidationError(
                {"flow_id": "This ABHA session has expired. Start again."}
            )
        return cls(**data)

    @classmethod
    def load_or_start(cls, flow_id, user) -> "AbhaFlow":
        return cls.load(flow_id, user) if flow_id else cls.start(user)

    def save(self):
        cache.set(self._key(self.id), asdict(self), timeout=FLOW_TTL_SECONDS)

    def require_profile(self) -> dict:
        if not self.profile or not self.x_token:
            raise ValidationError({"flow_id": "Verify the ABHA before this step."})
        return self.profile
