{"content": """"The ABHA (M1) desk journey, as one API the frontend drives step by step.

Every response carries `status`, which names the next screen:
  otp_sent         -> ask for the OTP
  accounts_found   -> a free lookup found accounts; pick one (no OTP sent yet)
  select_account   -> OTP verified, several accounts; pick one
  not_found        -> nobody holds an ABHA for this identifier (ABDM-1114)
  authenticated    -> profile is ready; fill the form or link
"""

import re
from enum import Enum

from django.conf import settings
from django.db import transaction
from django.http import HttpResponse
from django.shortcuts import get_object_or_404
from pydantic import BaseModel, Field, field_validator
from rest_framework.decorators import action
from rest_framework.exceptions import NotFound, PermissionDenied, ValidationError
from rest_framework.response import Response
from rest_framework.viewsets import GenericViewSet

from care.abdm.models import AbhaNumber
from care.abdm.service import abha
from care.abdm.service.abha import GATEWAY_AUTH_FAILURES
from care.abdm.service.crypto import UnsupportedEncryptionAlgorithmError
from care.abdm.service.errors import AbdmError
from care.abdm.service.flow import AbhaFlow
from care.abdm.service.profile import normalize_profile, summarize_account
from care.emr.api.viewsets.base import emr_exception_handler
from care.emr.models import Patient
from care.security.authorization import AuthorizationController

NOT_FOUND_CODE = "ABDM-1114"
ABHA_ADDRESS_PATTERN = re.compile(r"^[A-Za-z][A-Za-z0-9.]*[A-Za-z0-9]$")
LOGIN_SCOPES = {
    ("aadhaar", "aadhaar"): ["abha-login", "aadhaar-verify"],
    ("abha-number", "aadhaar"): ["abha-login", "aadhaar-verify"],
    ("abha-number", "abdm"): ["abha-login", "mobile-verify"],
}


def abdm_exception_handler(exc, context):
    if isinstance(exc, AbdmError):
        upstream = (
            exc.status >= 500  # noqa: PLR2004
            or any(exc.has_code(code) for code in GATEWAY_AUTH_FAILURES)
            or (exc.status == 401 and not exc.code)  # noqa: PLR2004
        )
        # Never pass ABDM's 401 through: the frontend reads 401 as Care's own session expiring.
        return Response(
            {
                "errors": [
                    {
                        "type": "abdm_error",
                        "code": exc.code,
                        "msg": exc.message,
                        "fields": exc.fields,
                        "request_id": exc.request_id,
                    }
                ]
            },
            status=502 if upstream else 400,
        )
    if isinstance(exc, UnsupportedEncryptionAlgorithmError):
        return Response(
            {
                "errors": [
                    {
                        "type": "abdm_error",
                        "msg": f"ABDM published an encryption algorithm Care does not support: {exc}",
                    }
                ]
            },
            status=502,
        )
    return emr_exception_handler(exc, context)


def _digits(value: str) -> str:
    return re.sub(r"\D", "", value or "")


class IdentifierType(str, Enum):
    aadhaar = "aadhaar"
    mobile = "mobile"
    abha_number = "abha_number"


class OtpSystem(str, Enum):
    aadhaar = "aadhaar"
    abdm = "abdm"


class FlowRequest(BaseModel):
    flow_id: str


class IdentifyRequest(BaseModel):
    flow_id: str | None = None
    identifier_type: IdentifierType
    value: str = Field(min_length=1)
    otp_system: OtpSystem = OtpSystem.abdm

    @field_validator("value")
    @classmethod
    def strip_value(cls, value):
        return value.strip()


class OtpRequest(FlowRequest):
    otp: str = Field(min_length=4, max_length=8)


class SearchAccountRequest(FlowRequest):
    index: int


class SelectAccountRequest(FlowRequest):
    abha_number: str


class EnrolRequestOtpRequest(FlowRequest):
    resend: bool = False


class EnrolVerifyOtpRequest(OtpRequest):
    mobile: str | None = None


class MobileRequest(FlowRequest):
    mobile: str


class AddressRequest(FlowRequest):
    abha_address: str


class DemographicRequest(BaseModel):
    flow_id: str | None = None
    aadhaar: str
    name: str
    date_of_birth: str = Field(description="dd-MM-yyyy, as on Aadhaar")
    gender: str = Field(pattern="^[MFO]$")
    state_code: str
    district_code: str
    mobile: str | None = None
    pincode: str | None = None
    address: str | None = None


class LinkRequest(FlowRequest):
    patient: str


def serialize_abha_number(obj: AbhaNumber) -> dict:
    return {
        "id": str(obj.external_id),
        "patient": str(obj.patient.external_id) if obj.patient else None,
        "abha_number": obj.abha_number,
        "abha_address": obj.abha_address,
        "name": obj.name,
        "gender": obj.gender,
        "date_of_birth": obj.date_of_birth,
        "year_of_birth": obj.year_of_birth,
        "mobile": obj.mobile,
        "kyc_verified": obj.kyc_verified,
        "status": obj.status,
        "profile": obj.profile,
        "modified_date": obj.modified_date,
    }


class AbhaViewSet(GenericViewSet):
    def get_exception_handler(self):
        return abdm_exception_handler

    def initial(self, request, *args, **kwargs):
        super().initial(request, *args, **kwargs)
        if not settings.ABDM_ENABLED:
            raise NotFound("ABDM is not enabled on this deployment")
        if self.action not in ("config", "patient", "link") and not (
            AuthorizationController.call("can_create_patient", request.user)
        ):
            raise PermissionDenied("You do not have permission to verify ABHA")

    # Responses

    def _otp_sent(self, flow, data):
        flow.save()
        return Response(
            {"status": "otp_sent", "flow_id": flow.id, "message": data.get("message")}
        )

    def _not_found(self, flow):
        flow.save()
        return Response({"status": "not_found", "flow_id": flow.id})

    def _linked_patient(self, abha_number):
        record = (
            AbhaNumber.objects.filter(abha_number=abha_number, patient__isnull=False)
            .select_related("patient")
            .first()
        )
        if not record:
            return None
        if AuthorizationController.call(
            "can_view_patient_obj", self.request.user, record.patient
        ):
            return {"id": str(record.patient.external_id), "name": record.patient.name}
        return {"id": None, "name": None}

    def _authenticate(self, flow, x_token, profile=None, **extra):
        flow.x_token = x_token
        flow.t_token = None
        if profile is None:
            profile = abha.get_profile(x_token=x_token)
        flow.profile = normalize_profile(profile)
        flow.save()
        return Response(
            {
                "status": "authenticated",
                "flow_id": flow.id,
                "profile": flow.profile,
                "linked_patient": self._linked_patient(flow.profile["abha_number"]),
                **extra,
            }
        )

    # Configuration

    @action(detail=False, methods=["GET"])
    def config(self, request):
        return Response(
            {
                "enabled": settings.ABDM_ENABLED,
                "demographic_auth_enabled": settings.ABDM_DEMOGRAPHIC_AUTH_ENABLED,
            }
        )

    # Identify: every identifier starts on a lookup, never on enrolment.

    @action(detail=False, methods=["POST"])
    def identify(self, request):
        data = IdentifyRequest(**request.data)
        flow = AbhaFlow.load_or_start(data.flow_id, request.user)
        flow.txn_id = None
        flow.t_token = None
        flow.x_token = None
        flow.profile = None

        if data.identifier_type == IdentifierType.mobile:
            return self._identify_mobile(flow, _digits(data.value))

        if data.identifier_type == IdentifierType.aadhaar:
            login_hint, otp_system = "aadhaar", "aadhaar"
            encrypted = abha.encrypt(_digits(data.value))
            flow.encrypted_aadhaar = encrypted
        else:
            login_hint, otp_system = "abha-number", data.otp_system.value
            value = data.value
            if len(_digits(value)) == 14 and "-" not in value:  # noqa: PLR2004
                # Observed: the sandbox refuses an ABHA number without its dashes.
                d = _digits(value)
                value = f"{d[:2]}-{d[2:6]}-{d[6:10]}-{d[10:]}"
            encrypted = abha.encrypt(value)

        scope = LOGIN_SCOPES[(login_hint, otp_system)]
        try:
            response = abha.login_request_otp(
                scope=scope,
                login_hint=login_hint,
                encrypted_login_id=encrypted,
                otp_system=otp_system,
            )
        except AbdmError as e:
            if e.has_code(NOT_FOUND_CODE):
                return self._not_found(flow)
            raise
        flow.txn_id = response.get("txnId")
        flow.verify_scope = scope
        return self._otp_sent(flow, response)

    def _identify_mobile(self, flow, mobile):
        flow.mobile = mobile
        try:
            response = abha.search_by_mobile(mobile)
        except AbdmError as e:
            if e.has_code(NOT_FOUND_CODE):
                return self._not_found(flow)
            raise
        results = response if isinstance(response, list) else [response]
        flow.search_results = [
            {
                "txn_id": result.get("txnId"),
                "index": account.get("index"),
                "abha_number": account.get("ABHANumber"),
                "name": account.get("name"),
                "gender": account.get("gender"),
                "kyc_verified": account.get("kycVerified"),
                "auth_methods": account.get("authMethods") or [],
            }
            for result in results
            for account in (result.get("ABHA") or [])
        ]
        if not flow.search_results:
            return self._not_found(flow)
        flow.save()
        return Response(
            {
                "status": "accounts_found",
                "flow_id": flow.id,
                "accounts": [
                    {k: v for k, v in r.items() if k != "txn_id"}
                    for r in flow.search_results
                ],
            }
        )

    @action(detail=False, methods=["POST"], url_path="search-account")
    def search_account(self, request):
        data = SearchAccountRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        result = next((r for r in flow.search_results if r["index"] == data.index), None)
        if not result:
            raise ValidationError({"index": "Pick one of the accounts found."})
        response = abha.login_request_otp(
            scope=["abha-login", "search-abha", "mobile-verify"],
            login_hint="index",
            encrypted_login_id=abha.encrypt(str(data.index)),
            otp_system="abdm",
            txn_id=result["txn_id"],
        )
        flow.txn_id = response.get("txnId", result["txn_id"])
        flow.verify_scope = ["abha-login", "mobile-verify"]
        return self._otp_sent(flow, response)

    @action(detail=False, methods=["POST"], url_path="verify-otp")
    def verify_otp(self, request):
        data = OtpRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        if not flow.txn_id or not flow.verify_scope:
            raise ValidationError({"flow_id": "Request an OTP first."})
        response = abha.login_verify_otp(
            scope=flow.verify_scope, txn_id=flow.txn_id, otp=data.otp
        )
        flow.txn_id = response.get("txnId", flow.txn_id)
        accounts = response.get("accounts") or []

        # A refreshToken means this is already the user token; without one it is
        # a short-lived T-token that must be exchanged for the chosen account.
        if response.get("refreshToken"):
            return self._authenticate(flow, response["token"])

        flow.t_token = response.get("token")
        flow.accounts = [summarize_account(a) for a in accounts]
        if len(accounts) == 1:
            return self._select(flow, accounts[0]["ABHANumber"])
        flow.save()
        return Response(
            {"status": "select_account", "flow_id": flow.id, "accounts": flow.accounts}
        )

    @action(detail=False, methods=["POST"], url_path="select-account")
    def select_account(self, request):
        data = SelectAccountRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        if data.abha_number not in {a["abha_number"] for a in flow.accounts}:
            raise ValidationError({"abha_number": "Pick one of the accounts listed."})
        return self._select(flow, data.abha_number)

    def _select(self, flow, abha_number):
        if not flow.t_token:
            raise ValidationError({"flow_id": "Verify the OTP first."})
        response = abha.login_verify_user(
            abha_number=abha_number, txn_id=flow.txn_id, t_token=flow.t_token
        )
        return self._authenticate(flow, response["token"])

    # Create, only reached after the lookup answered ABDM-1114.

    @action(detail=False, methods=["POST"], url_path="enrol/request-otp")
    def enrol_request_otp(self, request):
        data = EnrolRequestOtpRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        if not flow.encrypted_aadhaar:
            raise ValidationError(
                {"flow_id": "Look up the Aadhaar number before creating an ABHA."}
            )
        response = abha.enrol_request_otp(
            encrypted_aadhaar=flow.encrypted_aadhaar,
            txn_id=flow.txn_id if data.resend else None,
        )
        flow.txn_id = response.get("txnId")
        flow.verify_scope = []
        return self._otp_sent(flow, response)

    @action(detail=False, methods=["POST"], url_path="enrol/verify-otp")
    def enrol_verify_otp(self, request):
        data = EnrolVerifyOtpRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        mobile = _digits(data.mobile or flow.mobile or "") or None
        flow.mobile = mobile
        response = abha.enrol_by_aadhaar_otp(txn_id=flow.txn_id, otp=data.otp, mobile=mobile)
        flow.txn_id = response.get("txnId", flow.txn_id)
        profile = response.get("ABHAProfile") or {}
        linked_mobile = str(profile.get("mobile") or "")
        return self._authenticate(
            flow,
            (response.get("tokens") or {}).get("token"),
            profile=profile,
            is_new=bool(response.get("isNew")),
            message=response.get("message"),
            # The profile returns the mobile masked, so only the last four digits compare.
            mobile_verification_required=bool(
                mobile and linked_mobile[-4:] != mobile[-4:]
            ),
        )

    @action(detail=False, methods=["POST"], url_path="enrol/demographic")
    def enrol_demographic(self, request):
        if not settings.ABDM_DEMOGRAPHIC_AUTH_ENABLED:
            raise PermissionDenied("Demographic authentication is not enabled")
        data = DemographicRequest(**request.data)
        flow = AbhaFlow.load_or_start(data.flow_id, request.user)
