    @action(detail=False, methods=["POST"], url_path="enrol/address")
    def create_address(self, request):
        data = AddressRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        flow.require_profile()
        address = data.abha_address.strip().split("@")[0]
        if not ABHA_ADDRESS_PATTERN.match(address):
            raise ValidationError(
                {
                    "abha_address": "Use letters, digits and dots; start with a letter "
                    "and do not end with a dot."
                }
            )
        response = abha.create_address(txn_id=flow.txn_id, address=address)
        flow.profile["abha_address"] = response.get("preferredAbhaAddress") or address
        flow.profile["abha_addresses"] = [
            flow.profile["abha_address"],
            *[a for a in flow.profile["abha_addresses"] if a != flow.profile["abha_address"]],
        ]
        flow.save()
        return Response(
            {"status": "authenticated", "flow_id": flow.id, "profile": flow.profile}
        )

    # Profile placements, all on the verified user token

    @action(detail=False, methods=["POST"])
