        data = FlowRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        flow.require_profile()
        return self._authenticate(flow, flow.x_token)

    def _passthrough(self, fetch):
        flow = AbhaFlow.load(self.request.query_params.get("flow_id"), self.request.user)
        flow.require_profile()
        response = fetch(x_token=flow.x_token)
        return HttpResponse(
            response.content,
            content_type=response.headers.get("Content-Type", "image/png"),
        )

    @action(detail=False, methods=["GET"])
    def card(self, request):
        return self._passthrough(abha.get_card)

    @action(detail=False, methods=["GET"], url_path="qr-code")
    def qr_code(self, request):
        return self._passthrough(abha.get_qr_code)

    @action(detail=False, methods=["POST"], url_path="mobile/request-otp")
    def mobile_request_otp(self, request):
        data = MobileRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        flow.require_profile()
        flow.mobile = _digits(data.mobile)
        response = abha.profile_request_mobile_otp(x_token=flow.x_token, mobile=flow.mobile)
        flow.txn_id = response.get("txnId")
        return self._otp_sent(flow, response)

    @action(detail=False, methods=["POST"], url_path="mobile/verify-otp")
    def mobile_verify_otp(self, request):
        data = OtpRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        flow.require_profile()
        response = abha.profile_verify_mobile_otp(
            x_token=flow.x_token, txn_id=flow.txn_id, otp=data.otp
        )
        if response.get("authResult") != "success":
            raise ValidationError({"otp": response.get("message") or "Mobile not updated"})
        return self._authenticate(flow, flow.x_token, message=response.get("message"))

    # Persisting the verified ABHA against a Care patient

    @action(detail=False, methods=["POST"])
    def link(self, request):
        data = LinkRequest(**request.data)
        flow = AbhaFlow.load(data.flow_id, request.user)
        profile = flow.require_profile()
        patient = get_object_or_404(Patient, external_id=data.patient)
        if not AuthorizationController.call(
            "can_write_patient_obj", request.user, patient
        ):
            raise PermissionDenied("You do not have permission to update this patient")

        with transaction.atomic():
            existing_for_patient = AbhaNumber.objects.filter(patient=patient).first()
            if (
                existing_for_patient
                and existing_for_patient.abha_number != profile["abha_number"]
            ):
                raise ValidationError(
                    {"patient": "This patient is already linked to a different ABHA."}
                )
            record = (
                AbhaNumber.objects.select_for_update()
                .filter(abha_number=profile["abha_number"])
                .first()
            ) or AbhaNumber(abha_number=profile["abha_number"], created_by=request.user)
            if record.patient_id and record.patient_id != patient.id:
                raise ValidationError(
                    {"abha_number": "This ABHA is already linked to another patient."}
                )
            record.patient = patient
            record.abha_address = profile.get("abha_address") or ""
            record.name = profile.get("name") or ""
            record.gender = profile.get("gender") or ""
            record.date_of_birth = profile.get("date_of_birth")
            record.year_of_birth = profile.get("year_of_birth")
            record.mobile = profile.get("mobile") or ""
            record.kyc_verified = profile.get("kyc_verified")
            record.status = profile.get("status") or ""
            record.profile = {k: v for k, v in profile.items() if k != "photo"}
            record.updated_by = request.user
            record.save()
        return Response(serialize_abha_number(record))

    @action(detail=False, methods=["GET"])
    def patient(self, request):
        patient = get_object_or_404(
            Patient, external_id=request.query_params.get("patient")
        )
        if not AuthorizationController.call(
            "can_view_patient_obj", request.user, patient
        ):
            raise PermissionDenied("You do not have permission to view this patient")
        record = AbhaNumber.objects.filter(patient=patient).first()
        if not record:
            raise NotFound("No ABHA is linked to this patient")
        return Response(serialize_abha_number(record))
