{"content": "import { useQuery } from "@tanstack/react-query";

import abhaApi from "@/types/abdm/abhaApi";
import query from "@/Utils/request/query";
import { HTTPError } from "@/Utils/request/types";
import { getAuthorizationHeader } from "@/Utils/request/utils";
import careConfig from "@careConfig";

export function useAbdmConfig() {
  const { data } = useQuery({
    queryKey: ["abdm", "config"],
    // A deployment without ABDM answers 404; that only means "off".
    queryFn: query(abhaApi.config, { silent: true }),
    staleTime: Infinity,
    retry: false,
  });
  return {
    enabled: !!data?.enabled,
    demographicAuthEnabled: !!data?.demographic_auth_enabled,
  };
}

interface AbdmErrorDetail {
  msg?: string;
  code?: string | null;
  request_id?: string;
  fields?: Record<string, string>;
}

export interface AbdmErrorMessage {
  message: string;
  code?: string;
  requestId?: string;
  fields: string[];
}

export function getAbdmError(
  error: unknown,
  fallback: string,
): AbdmErrorMessage {
  if (!(error instanceof HTTPError)) {
    return { message: fallback, fields: [] };
  }
  const errors = (error.cause as { errors?: AbdmErrorDetail[] } | undefined)
    ?.errors;
  const first = Array.isArray(errors) ? errors[0] : undefined;
  if (!first) {
    const detail = (error.cause as { detail?: string } | undefined)?.detail;
    return { message: detail || fallback, fields: [] };
  }
  return {
    message: typeof first.msg === "string" ? first.msg : fallback,
    code: first.code ?? undefined,
    requestId: first.request_id,
    fields: Object.keys(first.fields ?? {}),
  };
}

export async function fetchAbhaImage(path: string, flowId: string) {
  const url = `${careConfig.apiUrl}${path}?flow_id=${encodeURIComponent(flowId)}`;
  const response = await fetch(url, {
    headers: { Authorization: getAuthorizationHeader() ?? "" },
  });
  if (!response.ok) {
    throw new Error(`HTTP ${response.status}`);
  }
  return URL.createObjectURL(await response.blob());
}

export function isIndianMobile(value?: string | null) {
  return /^[6-9]\d{9}$/.test(toIndianMobile(value));
}

export function toIndianMobile(value?: string | null) {
  const digits = (value ?? "").replace(/\D/g, "");
  return digits.length === 12 && digits.startsWith("91")
    ? digits.slice(2)
    : digits;
}

export function formatAbhaNumber(value: string) {
  const digits = value.replace(/\D/g, "").slice(0, 14);
  return [digits.slice(0, 2), digits.slice(2, 6), digits.slice(6, 10), digits.slice(10)]
    .filter(Boolean)
    .join("-");
}
