{"content": "import { useMutation } from "@tanstack/react-query";
import { REGEXP_ONLY_DIGITS } from "input-otp";
import { CheckCircle2Icon, ShieldCheckIcon, UserRoundIcon } from "lucide-react";
import { navigate } from "raviger";
import { useEffect, useRef, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";

import {
  AbdmErrorMessage,
  formatAbhaNumber,
  getAbdmError,
  toIndianMobile,
  useAbdmConfig,
} from "@/components/Abdm/utils";

import {
  AbhaAccountSummary,
  AbhaAuthenticatedResponse,
  AbhaFlowResponse,
  AbhaIdentifierType,
  AbhaOtpSystem,
  AbhaSearchResult,
} from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import { callApi } from "@/Utils/request/query";
import { ApiRoute } from "@/Utils/request/types";

type OtpPurpose = "login" | "enrol" | "enrol_mobile";

type Step =
  | { name: "identify" }
  | { name: "accounts_found"; accounts: AbhaSearchResult[] }
  | { name: "otp"; purpose: OtpPurpose; message: string | null }
  | { name: "select_account"; accounts: AbhaAccountSummary[] }
  | { name: "not_found" }
  | { name: "demographic" }
  | { name: "mobile_verify" }
  | { name: "address"; suggestions: string[] }
  | { name: "done" };

const RESEND_WAIT_SECONDS = 60;

export interface AbhaInitialIdentifier {
  type: AbhaIdentifierType;
  value: string;
  /** The desk already holds this identifier, so the field is not editable. */
  locked?: boolean;
}

interface AbhaVerifyDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  onAuthenticated: (result: AbhaAuthenticatedResponse) => void;
  initialIdentifier?: AbhaInitialIdentifier;
  /** Whether a new ABHA may be created when the lookup finds none. */
  allowCreate?: boolean;
  facilityId?: string;
  title?: string;
}

export default function AbhaVerifyDialog({
  open,
  onOpenChange,
  title,
  ...props
}: AbhaVerifyDialogProps) {
  const { t } = useTranslation();
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-lg max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <ShieldCheckIcon className="size-5 text-primary-700" />
            {title ?? t("abha_find_or_create")}
          </DialogTitle>
          <DialogDescription>{t("abha_dialog_description")}</DialogDescription>
        </DialogHeader>
        {open && (
          <AbhaJourney {...props} onClose={() => onOpenChange(false)} />
        )}
      </DialogContent>
    </Dialog>
  );
}

function AbhaJourney({
  onAuthenticated,
  initialIdentifier,
  allowCreate = true,
  facilityId,
  onClose,
}: Omit<AbhaVerifyDialogProps, "open" | "onOpenChange" | "title"> & {
  onClose: () => void;
}) {
  const { t } = useTranslation();
  const { demographicAuthEnabled } = useAbdmConfig();

  const [step, setStep] = useState<Step>({ name: "identify" });
  const [flowId, setFlowId] = useState<string>();
  const [identifierType, setIdentifierType] = useState<AbhaIdentifierType>(
    initialIdentifier?.type ?? "aadhaar",
  );
  const [value, setValue] = useState(initialIdentifier?.value ?? "");
  const [otpSystem, setOtpSystem] = useState<AbhaOtpSystem>("abdm");
  const [aadhaarConsent, setAadhaarConsent] = useState(false);
  // Facts carried between steps so the desk is never asked twice.
  const [mobile, setMobile] = useState(
    initialIdentifier?.type === "mobile" ? initialIdentifier.value : "",
  );
  const [result, setResult] = useState<AbhaAuthenticatedResponse>();
  const [error, setError] = useState<AbdmErrorMessage | null>(null);
  const resendRef = useRef<() => Promise<AbhaFlowResponse>>(undefined);

  const api = <R extends ApiRoute<unknown, unknown>>(
    route: R,
    body: R["TBody"],
  ) => callApi(route, { body, silent: true });

  const { mutate: run, isPending } = useMutation({
    mutationFn: (fn: () => Promise<void>) => fn(),
    onMutate: () => setError(null),
    onError: (e) => setError(getAbdmError(e, t("abha_request_failed"))),
  });

  const lockedIdentifier = !!initialIdentifier?.locked;

  async function handleFlowResponse(
    response: AbhaFlowResponse,
    purpose: OtpPurpose,
  ) {
    setFlowId(response.flow_id);
    switch (response.status) {
      case "otp_sent":
        setStep({ name: "otp", purpose, message: response.message });
        return;
      case "accounts_found":
        setStep({ name: "accounts_found", accounts: response.accounts });
        return;
      case "select_account":
        setStep({ name: "select_account", accounts: response.accounts });
        return;
      case "not_found":
        setStep({ name: "not_found" });
        return;
      case "authenticated":
        await handleAuthenticated(response);
        return;
    }
  }

  async function handleAuthenticated(response: AbhaAuthenticatedResponse) {
    setResult(response);
    if (response.mobile_verification_required) {
      setStep({ name: "mobile_verify" });
      return;
    }
    if (response.is_new) {
      const { suggestions } = await api(abhaApi.addressSuggestions, {
        flow_id: response.flow_id,
      });
      setStep({ name: "address", suggestions });
      return;
    }
    setStep({ name: "done" });
  }

  const handleIdentify = () =>
    run(async () => {
      const request = () =>
        api(abhaApi.identify, {
          flow_id: flowId,
          identifier_type: identifierType,
          value,
          otp_system: identifierType === "abha_number" ? otpSystem : undefined,
        });
      if (identifierType === "mobile") {
        setMobile(toIndianMobile(value));
      }
      resendRef.current = request;
      await handleFlowResponse(await request(), "login");
    });

  const handlePickSearchResult = (index: number) =>
    run(async () => {
      const request = () =>
        api(abhaApi.searchAccount, { flow_id: flowId!, index });
      resendRef.current = request;
      await handleFlowResponse(await request(), "login");
    });

  const handleSelectAccount = (abhaNumber: string) =>
    run(async () => {
      await handleAuthenticated(
        await api(abhaApi.selectAccount, {
          flow_id: flowId!,
          abha_number: abhaNumber,
        }),
      );
    });

  const handleStartEnrolment = () =>
    run(async () => {
      resendRef.current = () =>
        api(abhaApi.enrolRequestOtp, { flow_id: flowId!, resend: true });
      const response = await api(abhaApi.enrolRequestOtp, {
        flow_id: flowId!,
      });
      await handleFlowResponse(response, "enrol");
    });

  const handleVerifyOtp = (purpose: OtpPurpose, otp: string) =>
    run(async () => {
      if (purpose === "login") {
        await handleFlowResponse(
          await api(abhaApi.verifyOtp, { flow_id: flowId!, otp }),
          "login",
        );
      } else if (purpose === "enrol") {
        await handleAuthenticated(
          await api(abhaApi.enrolVerifyOtp, {
            flow_id: flowId!,
            otp,
            mobile: toIndianMobile(mobile) || undefined,
          }),
        );
      } else {
        const response = await api(abhaApi.enrolMobileVerifyOtp, {
          flow_id: flowId!,
          otp,
        });
        await handleAuthenticated({ ...result!, ...response, is_new: result?.is_new });
      }
    });

  const handleResend = (purpose: OtpPurpose) =>
    run(async () => {
      if (!resendRef.current) return;
      await handleFlowResponse(await resendRef.current(), purpose);
    });

  const handleRequestMobileOtp = () =>
    run(async () => {
      const request = () =>
        api(abhaApi.enrolMobileRequestOtp, {
          flow_id: flowId!,
          mobile: toIndianMobile(mobile),
        });
      resendRef.current = request;
      await handleFlowResponse(await request(), "enrol_mobile");
    });

  const handleSkipMobile = () =>
    run(async () => {
      await handleAuthenticated({
        ...result!,
        mobile_verification_required: false,
      });
    });

  const handleCreateAddress = (address: string) =>
    run(async () => {
      const response = await api(abhaApi.createAddress, {
        flow_id: flowId!,
        abha_address: address,
      });
      setResult({ ...result!, profile: response.profile });
      setStep({ name: "done" });
    });

  const handleConfirm = () => {
    if (result) {
      onAuthenticated(result);
    }
    onClose();
  };

  const switchToAadhaar = () => {
    setIdentifierType("aadhaar");
    setValue("");
    setStep({ name: "identify" });
  };

  return (
    <div className="flex flex-col gap-4">
      {error && <AbdmErrorAlert error={error} />}

      {step.name === "identify" && (
        <IdentifyStep
          identifierType={identifierType}
          onIdentifierTypeChange={(type) => {
            setIdentifierType(type);
            setValue(type === "mobile" ? mobile : "");
          }}
          value={value}
          onValueChange={setValue}
          otpSystem={otpSystem}
          onOtpSystemChange={setOtpSystem}
          aadhaarConsent={aadhaarConsent}
          onAadhaarConsentChange={setAadhaarConsent}
          locked={lockedIdentifier}
          isPending={isPending}
          onSubmit={handleIdentify}
        />
      )}

      {step.name === "accounts_found" && (
        <AccountList
          title={t("abha_accounts_found_title", {
            count: step.accounts.length,
          })}
          description={t("abha_accounts_found_description")}
          accounts={step.accounts.map((a) => ({
            key: String(a.index),
            name: a.name,
            abhaNumber: a.abha_number,
            gender: a.gender,
            kycVerified: a.kyc_verified,
          }))}
          actionLabel={t("abha_send_otp")}
          isPending={isPending}
          onPick={(key) => handlePickSearchResult(Number(key))}
        />
      )}

      {step.name === "select_account" && (
        <AccountList
          title={t("abha_select_account_title")}
          description={t("abha_select_account_description")}
          accounts={step.accounts.map((a) => ({
            key: a.abha_number,
            name: a.name,
            abhaNumber: a.abha_number,
            abhaAddress: a.abha_address,
            gender: a.gender,
            kycVerified: a.kyc_verified,
            photo: a.photo,
          }))}
          actionLabel={t("abha_use_this_account")}
          isPending={isPending}
          onPick={handleSelectAccount}
        />
      )}

      {step.name === "otp" && (
        <OtpStep
          key={`${step.purpose}-${step.message}`}
          message={step.message}
          showMobile={step.purpose === "enrol"}
          mobile={mobile}
          onMobileChange={setMobile}
          isPending={isPending}
          onVerify={(otp) => handleVerifyOtp(step.purpose, otp)}
          onResend={() => handleResend(step.purpose)}
        />
      )}

      {step.name === "not_found" && (
        <NotFoundStep
          identifierType={identifierType}
          allowCreate={allowCreate}
          demographicAuthEnabled={demographicAuthEnabled}
          isPending={isPending}
          onCreate={handleStartEnrolment}
          onCreateDemographic={() => setStep({ name: "demographic" })}
          onUseAadhaar={switchToAadhaar}
        />
      )}

      {step.name === "demographic" && (
        <DemographicStep
          mobile={mobile}
          isPending={isPending}
          onSubmit={(body) =>
            run(async () => {
              await handleAuthenticated(
                await api(abhaApi.enrolDemographic, {
                  ...body,
                  flow_id: flowId,
                }),
              );
            })
          }
        />
      )}

      {step.name === "mobile_verify" && (
        <div className="flex flex-col gap-3">
          <p className="text-sm text-gray-700">
            {t("abha_mobile_verify_description")}
          </p>
          <div className="flex flex-col gap-1.5">
            <Label htmlFor="abha-mobile-verify">{t("phone_number")}</Label>
            <Input
              id="abha-mobile-verify"
              inputMode="numeric"
              value={mobile}
              onChange={(e) => setMobile(e.target.value)}
            />
          </div>
          <div className="flex justify-end gap-2">
            <Button variant="ghost" onClick={handleSkipMobile} disabled={isPending}>
              {t("skip")}
            </Button>
            <Button
              variant="primary"
              onClick={handleRequestMobileOtp}
              disabled={isPending || toIndianMobile(mobile).length !== 10}
            >
              {t("abha_send_otp")}
            </Button>
          </div>
        </div>
      )}

      {step.name === "address" && result && (
        <AddressStep
          suggestions={step.suggestions}
          defaultAddress={result.profile.abha_address}
          isPending={isPending}
          onCreate={handleCreateAddress}
          onSkip={() => setStep({ name: "done" })}
        />
      )}

      {step.name === "done" && result && (
        <DoneStep
          result={result}
          facilityId={facilityId}
          onConfirm={handleConfirm}
        />
      )}

      <DialogFooter className="border-t pt-3">
        <Button variant="outline" onClick={onClose}>
          {t("abha_not_now")}
        </Button>
      </DialogFooter>
    </div>
  );
}

function AbdmErrorAlert({ error }: { error: AbdmErrorMessage }) {
  const { t } = useTranslation();
  return (
    <Alert variant="destructive" role="alert">
      <AlertTitle>{error.message}</AlertTitle>
      <AlertDescription className="flex flex-col gap-1 text-xs">
        {error.fields.length > 0 && (
          <span>
            {t("abha_field_refused_hint", { fields: error.fields.join(", ") })}
          </span>
        )}
        {(error.code || error.requestId) && (
          <span className="font-mono">
            {[error.code, error.requestId && `ref ${error.requestId}`]
              .filter(Boolean)
              .join(" · ")}
          </span>
        )}
      </AlertDescription>
    </Alert>
  );
}

const IDENTIFIER_TYPES: AbhaIdentifierType[] = [
  "aadhaar",
  "mobile",
  "abha_number",
];

function isIdentifierValid(type: AbhaIdentifierType, value: string) {
  const digits = value.replace(/\D/g, "");
  if (type === "aadhaar") return digits.length === 12;
  if (type === "mobile") return toIndianMobile(value).length === 10;
  return digits.length === 14;
}

function IdentifyStep({
  identifierType,
  onIdentifierTypeChange,
  value,
  onValueChange,
  otpSystem,
  onOtpSystemChange,
  aadhaarConsent,
  onAadhaarConsentChange,
  locked,
  isPending,
  onSubmit,
}: {
  identifierType: AbhaIdentifierType;
  onIdentifierTypeChange: (type: AbhaIdentifierType) => void;
  value: string;
  onValueChange: (value: string) => void;
  otpSystem: AbhaOtpSystem;
  onOtpSystemChange: (system: AbhaOtpSystem) => void;
  aadhaarConsent: boolean;
  onAadhaarConsentChange: (consent: boolean) => void;
  locked: boolean;
  isPending: boolean;
  onSubmit: () => void;
}) {
  const { t } = useTranslation();
  const needsConsent = identifierType === "aadhaar";
  const canSubmit =
    isIdentifierValid(identifierType, value) &&
    (!needsConsent || aadhaarConsent) &&
    !isPending;

  return (
    <form
      className="flex flex-col gap-4"
      onSubmit={(e) => {
        e.preventDefault();
        if (canSubmit) onSubmit();
      }}
    >
      {!locked && (
        <Tabs
          value={identifierType}
          onValueChange={(v) => onIdentifierTypeChange(v as AbhaIdentifierType)}
        >
          <TabsList className="w-full">
            {IDENTIFIER_TYPES.map((type) => (
              <TabsTrigger key={type} value={type} className="flex-1">
                {t(`abha_identifier__${type}`)}
              </TabsTrigger>
            ))}
          </TabsList>
        </Tabs>
      )}

      <div className="flex flex-col gap-1.5">
        <Label htmlFor="abha-identifier">
          {t(`abha_identifier__${identifierType}`)}
        </Label>
        <Input
          id="abha-identifier"
          autoFocus
          inputMode="numeric"
          autoComplete="off"
          disabled={locked}
          value={value}
          placeholder={t(`abha_identifier_placeholder__${identifierType}`)}
          onChange={(e) =>
            onValueChange(
              identifierType === "abha_number"
                ? formatAbhaNumber(e.target.value)
                : e.target.value,
            )
          }
        />
        {identifierType === "mobile" && (
          <p className="text-xs text-gray-500">{t("abha_mobile_lookup_hint")}</p>
        )}
      </div>

      {identifierType === "abha_number" && (
        <fieldset className="flex flex-col gap-2">
          <legend className="text-sm font-medium mb-1">
            {t("abha_send_otp_to")}
          </legend>
          <RadioGroup
            value={otpSystem}
            onValueChange={(v) => onOtpSystemChange(v as AbhaOtpSystem)}
          >
            {(["abdm", "aadhaar"] as const).map((system) => (
              <div key={system} className="flex items-center gap-2">
                <RadioGroupItem value={system} id={`abha-otp-${system}`} />
                <Label htmlFor={`abha-otp-${system}`}>
                  {t(`abha_otp_system__${system}`)}
                </Label>
              </div>
            ))}
          </RadioGroup>
        </fieldset>
      )}

      {needsConsent && (
        <div className="flex items-start gap-2">
          <Checkbox
            id="abha-aadhaar-consent"
            checked={aadhaarConsent}
            onCheckedChange={(checked) => onAadhaarConsentChange(!!checked)}
          />
          <Label
            htmlFor="abha-aadhaar-consent"
            className="text-xs font-normal text-gray-700 leading-snug"
          >
            {t("abha_aadhaar_consent")}
          </Label>
        </div>
      )}

      <Button type="submit" variant="primary" disabled={!canSubmit}>
        {isPending ? t("loading") : t("continue")}
      </Button>
    </form>
  );
}

interface AccountListItem {
  key: string;
  name: string | null;
  abhaNumber: string;
  abhaAddress?: string | null;
  gender: string | null;
  kycVerified: boolean | string | null;
  photo?: string | null;
}

function AccountList({
  title,
  description,
  accounts,
  actionLabel,
  isPending,
  onPick,
}: {
  title: string;
  description: string;
  accounts: AccountListItem[];
  actionLabel: string;
  isPending: boolean;
  onPick: (key: string) => void;
}) {
  const { t } = useTranslation();
  return (
    <div className="flex flex-col gap-3">
      <div>
        <h3 className="font-semibold">{title}</h3>
        <p className="text-sm text-gray-600">{description}</p>
      </div>
      <ul className="flex flex-col gap-2">
        {accounts.map((account) => (
          <li
            key={account.key}
            className="flex items-center gap-3 rounded-md border p-3"
          >
            {account.photo ? (
              <img
                src={`data:image/jpeg;base64,${account.photo}`}
                alt=""
                className="size-10 rounded-full object-cover"
              />
            ) : (
              <UserRoundIcon className="size-10 rounded-full bg-gray-100 p-2 text-gray-500" />
            )}
            <div className="flex-1 min-w-0">
              <p className="font-medium truncate">{account.name || "-"}</p>
              <p className="text-xs text-gray-600 font-mono">
                {account.abhaNumber}
                {account.abhaAddress && ` · ${account.abhaAddress}`}
              </p>
              {String(account.kycVerified) === "true" && (
                <Badge variant="green" className="mt-1">
                  {t("abha_kyc_verified")}
                </Badge>
              )}
            </div>
            <Button
              size="sm"
              variant="outline"
              disabled={isPending}
              onClick={() => onPick(account.key)}
            >
              {actionLabel}
            </Button>
          </li>
        ))}
      </ul>
    </div>
  );
}

function OtpStep({
  message,
  showMobile,
  mobile,
  onMobileChange,
  isPending,
  onVerify,
  onResend,
}: {
  message: string | null;
  showMobile: boolean;
  mobile: string;
  onMobileChange: (mobile: string) => void;
  isPending: boolean;
  onVerify: (otp: string) => void;
  onResend: () => void;
}) {
  const { t } = useTranslation();
  const [otp, setOtp] = useState("");
  const [wait, setWait] = useState(RESEND_WAIT_SECONDS);

  useEffect(() => {
    if (wait <= 0) return;
    const timer = setTimeout(() => setWait(wait - 1), 1000);
    return () => clearTimeout(timer);
  }, [wait]);

  return (
    <form
      className="flex flex-col gap-4"
      onSubmit={(e) => {
        e.preventDefault();
        if (otp.length === 6 && !isPending) onVerify(otp);
      }}
    >
      <p className="text-sm text-gray-700" aria-live="polite">
        {message || t("abha_otp_sent")}
      </p>
      <div className="flex flex-col items-center gap-2">
        <Label htmlFor="abha-otp" className="sr-only">
          {t("abha_otp")}
        </Label>
        <InputOTP
          id="abha-otp"
          maxLength={6}
          pattern={REGEXP_ONLY_DIGITS}
          value={otp}
          onChange={setOtp}
          autoFocus
        >
          <InputOTPGroup>
            {Array.from({ length: 6 }, (_, i) => (
              <InputOTPSlot key={i} index={i} />
            ))}
          </InputOTPGroup>
        </InputOTP>
      </div>
      {showMobile && (
        <div className="flex flex-col gap-1.5">
          <Label htmlFor="abha-enrol-mobile">{t("abha_mobile_to_link")}</Label>
          <Input
            id="abha-enrol-mobile"
            inputMode="numeric"
            value={mobile}
            onChange={(e) => onMobileChange(e.target.value)}
          />
          <p className="text-xs text-gray-500">
            {mobile ? t("abha_mobile_carried_hint") : t("abha_mobile_to_link_hint")}
          </p>
        </div>
      )}
      <div className="flex items-center justify-between gap-2">
        <Button
          type="button"
          variant="ghost"
          disabled={wait > 0 || isPending}
          onClick={() => {
            setOtp("");
            setWait(RESEND_WAIT_SECONDS);
            onResend();
          }}
        >
          {wait > 0
            ? t("abha_resend_in", { seconds: wait })
            : t("abha_resend_otp")}
        </Button>
        <Button
          type="submit"
          variant="primary"
          disabled={otp.length !== 6 || isPending}
        >
          {isPending ? t("loading") : t("verify")}
        </Button>
      </div>
    </form>
  );
}

function NotFoundStep({
  identifierType,
  allowCreate,
  demographicAuthEnabled,
  isPending,
  onCreate,
  onCreateDemographic,
  onUseAadhaar,
}: {
  identifierType: AbhaIdentifierType;
  allowCreate: boolean;
  demographicAuthEnabled: boolean;
  isPending: boolean;
  onCreate: () => void;
  onCreateDemographic: () => void;
  onUseAadhaar: () => void;
}) {
  const { t } = useTranslation();
  if (identifierType !== "aadhaar") {
    return (
      <div className="flex flex-col gap-3">
        <p className="text-sm text-gray-700">
          {t("abha_not_found_identifier", {
            identifier: t(`abha_identifier__${identifierType}`),
          })}
        </p>
        <Button variant="primary" onClick={onUseAadhaar}>
          {t("abha_try_aadhaar")}
        </Button>
      </div>
    );
  }
  return (
    <div className="flex flex-col gap-3">
      <p className="text-sm text-gray-700">{t("abha_not_found_aadhaar")}</p>
      {allowCreate && (
        <div className="flex flex-col gap-2">
          <Button variant="primary" disabled={isPending} onClick={onCreate}>
            {t("abha_create_with_aadhaar_otp")}
          </Button>
          {demographicAuthEnabled && (
            <Button
              variant="outline"
              disabled={isPending}
              onClick={onCreateDemographic}
            >
              {t("abha_create_with_demographics")}
            </Button>
          )}
        </div>
      )}
    </div>
  );
}

function DemographicStep({
  mobile,
  isPending,
  onSubmit,
}: {
  mobile: string;
  isPending: boolean;
  onSubmit: (body: {
    name: string;
    date_of_birth: string;
    gender: "M" | "F" | "O";
    state_code: string;
    district_code: string;
    mobile?: string;
    pincode?: string;
    address?: string;
  }) => void;
}) {
  const { t } = useTranslation();
  const [fields, setFields] = useState({
    name: "",
    dob: "",
    gender: "" as "" | "M" | "F" | "O",
    state_code: "",
    district_code: "",
    mobile,
    pincode: "",
    address: "",
  });
  const set = (key: keyof typeof fields) => (value: string) =>
    setFields((f) => ({ ...f, [key]: value }));
  const valid =
    fields.name && fields.dob && fields.gender && fields.state_code && fields.district_code;

  return (
    <form
      className="flex flex-col gap-3"
      onSubmit={(e) => {
        e.preventDefault();
        if (!valid || isPending) return;
        const [y, m, d] = fields.dob.split("-");
        onSubmit({
          name: fields.name,
          date_of_birth: `${d}-${m}-${y}`,
          gender: fields.gender as "M" | "F" | "O",
          state_code: fields.state_code,
          district_code: fields.district_code,
          mobile: toIndianMobile(fields.mobile) || undefined,
          pincode: fields.pincode || undefined,
          address: fields.address || undefined,
        });
      }}
    >
      <p className="text-sm text-gray-700">{t("abha_demographic_description")}</p>
      <LabeledInput id="abha-demo-name" label={t("abha_name_as_on_aadhaar")} value={fields.name} onChange={set("name")} />
      <LabeledInput id="abha-demo-dob" type="date" label={t("date_of_birth")} value={fields.dob} onChange={set("dob")} />
      <div className="flex flex-col gap-1.5">
        <Label>{t("sex")}</Label>
        <Select value={fields.gender} onValueChange={set("gender")}>
          <SelectTrigger>
            <SelectValue placeholder={t("select")} />
          </SelectTrigger>
          <SelectContent>
            {(["M", "F", "O"] as const).map((g) => (
              <SelectItem key={g} value={g}>
                {t(`abha_gender__${g}`)}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>
      <div className="grid grid-cols-2 gap-3">
        <LabeledInput id="abha-demo-state" label={t("abha_lgd_state_code")} value={fields.state_code} onChange={set("state_code")} />
        <LabeledInput id="abha-demo-district" label={t("abha_lgd_district_code")} value={fields.district_code} onChange={set("district_code")} />
      </div>
      <LabeledInput id="abha-demo-mobile" label={t("phone_number")} value={fields.mobile} onChange={set("mobile")} />
      <LabeledInput id="abha-demo-pincode" label={t("pincode")} value={fields.pincode} onChange={set("pincode")} />
      <LabeledInput id="abha-demo-address" label={t("address")} value={fields.address} onChange={set("address")} />
      <Button type="submit" variant="primary" disabled={!valid || isPending}>
        {isPending ? t("loading") : t("abha_create")}
      </Button>
    </form>
  );
}

function LabeledInput({
  id,
  label,
  value,
  onChange,
  type = "text",
}: {
  id: string;
  label: string;
  value: string;
  onChange: (value: string) => void;
  type?: string;
}) {
  return (
    <div className="flex flex-col gap-1.5">
      <Label htmlFor={id}>{label}</Label>
      <Input id={id} type={type} value={value} onChange={(e) => onChange(e.target.value)} />
    </div>
  );
}

const ABHA_ADDRESS_PATTERN = /^[A-Za-z][A-Za-z0-9.]*[A-Za-z0-9]$/;

function AddressStep({
  suggestions,
  defaultAddress,
  isPending,
  onCreate,
  onSkip,
}: {
  suggestions: string[];
  defaultAddress: string | null;
  isPending: boolean;
  onCreate: (address: string) => void;
  onSkip: () => void;
}) {
  const { t } = useTranslation();
  const [address, setAddress] = useState(suggestions[0] ?? "");
  const local = address.split("@")[0];
  const invalid = !!local && !ABHA_ADDRESS_PATTERN.test(local);

  return (
    <div className="flex flex-col gap-3">
      <p className="text-sm text-gray-700">
        {t("abha_address_description", { address: defaultAddress ?? "-" })}
      </p>
      {suggestions.length > 0 && (
        <div className="flex flex-wrap gap-2">
          {suggestions.map((s) => (
            <Button
              key={s}
              type="button"
              size="sm"
              variant={s === address ? "primary" : "outline"}
              onClick={() => setAddress(s)}
            >
              {s}
            </Button>
          ))}
        </div>
      )}
      <div className="flex flex-col gap-1.5">
        <Label htmlFor="abha-address">{t("abha_address")}</Label>
        <Input
          id="abha-address"
          value={address}
          aria-invalid={invalid}
          onChange={(e) => setAddress(e.target.value)}
        />
        <p className={invalid ? "text-xs text-red-600" : "text-xs text-gray-500"}>
          {t("abha_address_rules")}
        </p>
      </div>
      <div className="flex justify-end gap-2">
        <Button variant="ghost" onClick={onSkip} disabled={isPending}>
          {t("skip")}
        </Button>
        <Button
          variant="primary"
          disabled={!local || invalid || isPending}
          onClick={() => onCreate(local)}
        >
          {t("abha_create_address")}
        </Button>
      </div>
    </div>
  );
}

function DoneStep({
  result,
  facilityId,
  onConfirm,
}: {
  result: AbhaAuthenticatedResponse;
  facilityId?: string;
  onConfirm: () => void;
}) {
  const { t } = useTranslation();
  const { profile, linked_patient } = result;
  const dob =
    profile.date_of_birth ?? (profile.year_of_birth ? String(profile.year_of_birth) : "-");

  return (
    <div className="flex flex-col gap-4">
      <div className="flex items-center gap-2 text-green-700">
        <CheckCircle2Icon className="size-5" />
        <span className="font-medium">
          {result.is_new ? t("abha_created") : t("abha_verified")}
        </span>
      </div>
      <div className="flex gap-4 rounded-md border p-4">
        {profile.photo ? (
          <img
            src={`data:image/jpeg;base64,${profile.photo}`}
            alt=""
            className="size-16 rounded-md object-cover"
          />
        ) : (
          <UserRoundIcon className="size-16 rounded-md bg-gray-100 p-3 text-gray-500" />
        )}
        <dl className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1 text-sm">
          <dt className="text-gray-500">{t("name")}</dt>
          <dd className="font-medium">{profile.name}</dd>
          <dt className="text-gray-500">{t("abha_number")}</dt>
          <dd className="font-mono">{profile.abha_number}</dd>
          <dt className="text-gray-500">{t("abha_address")}</dt>
          <dd className="font-mono">{profile.abha_address ?? "-"}</dd>
          <dt className="text-gray-500">{t("date_of_birth")}</dt>
          <dd>{dob}</dd>
          <dt className="text-gray-500">{t("sex")}</dt>
          <dd>{profile.gender ? t(`abha_gender__${profile.gender}`) : "-"}</dd>
        </dl>
      </div>
      {profile.kyc_verified && (
        <Badge variant="green" className="self-start">
          {t("abha_kyc_verified")}
        </Badge>
      )}
      {linked_patient && (
        <Alert>
          <AlertTitle>{t("abha_already_linked_title")}</AlertTitle>
          <AlertDescription className="flex flex-col gap-2">
            <span>
              {linked_patient.name
                ? t("abha_already_linked_to", { name: linked_patient.name })
                : t("abha_already_linked_hidden")}
            </span>
            {linked_patient.id && (
              <Button
                variant="outline"
                size="sm"
                className="self-start"
                onClick={() =>
                  navigate(
                    facilityId
                      ? `/facility/${facilityId}/patient/${linked_patient.id}`
                      : `/patient/${linked_patient.id}`,
                  )
                }
              >
                {t("abha_open_existing_patient")}
              </Button>
            )}
          </AlertDescription>
        </Alert>
      )}
      <Button variant="primary" onClick={onConfirm}>
        {t("abha_use_these_details")}
      </Button>
    </div>
  );
}
