{"content": "import { useMutation, useQuery } from "@tanstack/react-query";
import { REGEXP_ONLY_DIGITS } from "input-otp";
import { useEffect, useState } from "react";
import { useTranslation } from "react-i18next";

import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp";
import { Label } from "@/components/ui/label";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";

import {
  AbdmErrorMessage,
  fetchAbhaImage,
  getAbdmError,
  toIndianMobile,
} from "@/components/Abdm/utils";

import { AbhaAuthenticatedResponse } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import { callApi } from "@/Utils/request/query";

interface AbhaAccountDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  session: AbhaAuthenticatedResponse;
  onProfileUpdated?: (session: AbhaAuthenticatedResponse) => void;
}

export default function AbhaAccountDialog({
  open,
  onOpenChange,
  session,
  onProfileUpdated,
}: AbhaAccountDialogProps) {
  const { t } = useTranslation();
  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-xl max-h-[90vh] overflow-y-auto">
        <DialogHeader>
          <DialogTitle>{session.profile.name}</DialogTitle>
          <DialogDescription className="font-mono">
            {session.profile.abha_number} · {session.profile.abha_address}
          </DialogDescription>
        </DialogHeader>
        {open && (
          <Tabs defaultValue="card">
            <TabsList className="w-full">
              <TabsTrigger value="card" className="flex-1">
                {t("abha_card")}
              </TabsTrigger>
              <TabsTrigger value="qr" className="flex-1">
                {t("abha_qr_code")}
              </TabsTrigger>
              <TabsTrigger value="mobile" className="flex-1">
                {t("abha_update_mobile")}
              </TabsTrigger>
            </TabsList>
            <TabsContent value="card">
              <AbhaImage path={abhaApi.card.path} flowId={session.flow_id} alt={t("abha_card")} />
            </TabsContent>
            <TabsContent value="qr">
              <AbhaImage path={abhaApi.qrCode.path} flowId={session.flow_id} alt={t("abha_qr_code")} />
            </TabsContent>
            <TabsContent value="mobile">
              <UpdateMobile session={session} onUpdated={onProfileUpdated} />
            </TabsContent>
          </Tabs>
        )}
      </DialogContent>
    </Dialog>
  );
}

function AbhaImage({
  path,
  flowId,
  alt,
}: {
  path: string;
  flowId: string;
  alt: string;
}) {
  const { t } = useTranslation();
  const { data: url, isLoading, isError } = useQuery({
    queryKey: ["abdm", "image", path, flowId],
    queryFn: () => fetchAbhaImage(path, flowId),
    staleTime: Infinity,
    retry: false,
  });

  useEffect(() => () => url && URL.revokeObjectURL(url), [url]);

  if (isLoading) {
    return <p className="p-6 text-center text-sm text-gray-500">{t("loading")}</p>;
  }
  if (isError || !url) {
    return (
      <Alert variant="destructive" className="mt-3">
        <AlertTitle>{t("abha_image_failed")}</AlertTitle>
      </Alert>
    );
  }
  return (
    <div className="flex flex-col items-center gap-3 pt-3">
      <img src={url} alt={alt} className="max-h-[60vh] rounded-md border" />
      <Button asChild variant="outline" size="sm">
        <a href={url} download={`${alt}.png`}>
          {t("download")}
        </a>
      </Button>
    </div>
  );
}

function UpdateMobile({
  session,
  onUpdated,
}: {
  session: AbhaAuthenticatedResponse;
  onUpdated?: (session: AbhaAuthenticatedResponse) => void;
}) {
  const { t } = useTranslation();
  const [mobile, setMobile] = useState("");
  const [otp, setOtp] = useState("");
  const [sentMessage, setSentMessage] = useState<string | null>();
  const [done, setDone] = useState<string | null>(null);
  const [error, setError] = useState<AbdmErrorMessage | null>(null);

  const { mutate: run, isPending } = useMutation({
    mutationFn: (fn: () => Promise<void>) => fn(),
    onMutate: () => setError(null),
    onError: (e) => setError(getAbdmError(e, t("abha_request_failed"))),
  });

  const requestOtp = () =>
    run(async () => {
      const response = await callApi(abhaApi.mobileRequestOtp, {
        body: { flow_id: session.flow_id, mobile: toIndianMobile(mobile) },
        silent: true,
      });
      setSentMessage(
        response.status === "otp_sent" ? response.message : null,
      );
    });

  const verify = () =>
    run(async () => {
      const response = await callApi(abhaApi.mobileVerifyOtp, {
        body: { flow_id: session.flow_id, otp },
        silent: true,
      });
      setDone(response.message ?? t("abha_mobile_updated"));
      onUpdated?.(response);
    });

  if (done) {
    return (
      <Alert className="mt-3">
        <AlertTitle>{done}</AlertTitle>
      </Alert>
    );
  }

  return (
    <div className="flex flex-col gap-3 pt-3">
      {error && (
        <Alert variant="destructive">
          <AlertTitle>{error.message}</AlertTitle>
          {error.requestId && (
            <AlertDescription className="font-mono text-xs">
              {[error.code, `ref ${error.requestId}`].filter(Boolean).join(" · ")}
            </AlertDescription>
          )}
        </Alert>
      )}
      <p className="text-sm text-gray-700">
        {t("abha_update_mobile_description", {
          mobile: session.profile.mobile ?? "-",
        })}
      </p>
      <div className="flex flex-col gap-1.5">
        <Label htmlFor="abha-new-mobile">{t("abha_new_mobile")}</Label>
        <Input
          id="abha-new-mobile"
          inputMode="numeric"
          value={mobile}
          disabled={sentMessage !== undefined}
          onChange={(e) => setMobile(e.target.value)}
        />
      </div>
      {sentMessage === undefined ? (
        <Button
          variant="primary"
          disabled={toIndianMobile(mobile).length !== 10 || isPending}
          onClick={requestOtp}
        >
          {t("abha_send_otp")}
        </Button>
      ) : (
        <>
          <p className="text-sm text-gray-700" aria-live="polite">
            {sentMessage || t("abha_otp_sent")}
          </p>
          <InputOTP maxLength={6} pattern={REGEXP_ONLY_DIGITS} value={otp} onChange={setOtp}>
            <InputOTPGroup>
              {Array.from({ length: 6 }, (_, i) => (
                <InputOTPSlot key={i} index={i} />
              ))}
            </InputOTPGroup>
          </InputOTP>
          <Button
            variant="primary"
            disabled={otp.length !== 6 || isPending}
            onClick={verify}
          >
            {t("verify")}
          </Button>
        </>
      )}
    </div>
  );
}
