{"content": "import { ShieldCheckIcon, XIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import AbhaAccountDialog from "@/components/Abdm/AbhaAccountDialog";
import AbhaVerifyDialog from "@/components/Abdm/AbhaVerifyDialog";
import { isIndianMobile, toIndianMobile, useAbdmConfig } from "@/components/Abdm/utils";

import { AbhaAuthenticatedResponse, AbhaProfile } from "@/types/abdm/abha";

interface AbhaRegistrationPanelProps {
  facilityId?: string;
  /** The phone number already typed into the form, offered as the lookup. */
  phoneNumber?: string;
  /** Fills the form and returns the labels of the fields it filled. */
  onProfile: (profile: AbhaProfile) => string[];
  onSessionChange: (session: AbhaAuthenticatedResponse | null) => void;
}

/**
 * The ABHA step that comes before the registration form and fills it.
 * Optional: registration completes without it.
 */
export default function AbhaRegistrationPanel({
  facilityId,
  phoneNumber,
  onProfile,
  onSessionChange,
}: AbhaRegistrationPanelProps) {
  const { t } = useTranslation();
  const { enabled } = useAbdmConfig();
  const [open, setOpen] = useState(false);
  const [accountOpen, setAccountOpen] = useState(false);
  const [session, setSession] = useState<AbhaAuthenticatedResponse | null>(null);
  const [filled, setFilled] = useState<string[]>([]);

  if (!enabled) {
    return null;
  }

  const handleAuthenticated = (result: AbhaAuthenticatedResponse) => {
    setSession(result);
    setFilled(onProfile(result.profile));
    onSessionChange(result);
  };

  const handleRemove = () => {
    setSession(null);
    setFilled([]);
    onSessionChange(null);
  };

  return (
    <section
      aria-labelledby="abha-registration-heading"
      className="bg-white flex flex-col gap-3 p-6 shadow rounded-md"
    >
      <div className="flex items-start justify-between gap-4">
        <div>
          <h5
            id="abha-registration-heading"
            className="text-lg font-semibold flex items-center gap-2"
          >
            <ShieldCheckIcon className="size-5 text-primary-700" />
            {t("abha")} ({t("optional")})
          </h5>
          <p className="text-sm text-gray-600">
            {session ? t("abha_will_link_on_register") : t("abha_registration_description")}
          </p>
        </div>
        {!session && (
          <Button type="button" variant="outline" onClick={() => setOpen(true)}>
            {t("abha_find_or_create")}
          </Button>
        )}
      </div>

      {session && (
        <div className="flex flex-col gap-3 rounded-md border border-primary-200 bg-primary-50 p-4">
          <div className="flex items-start justify-between gap-2">
            <div className="text-sm">
              <p className="font-semibold">{session.profile.name}</p>
              <p className="font-mono text-gray-700">
                {session.profile.abha_number} · {session.profile.abha_address}
              </p>
            </div>
            <Button
              type="button"
              variant="ghost"
              size="icon"
              aria-label={t("abha_remove_from_form")}
              onClick={handleRemove}
            >
              <XIcon />
            </Button>
          </div>
          {filled.length > 0 && (
            <div className="flex flex-wrap items-center gap-1 text-xs text-gray-700">
              <span>{t("abha_filled_from_profile")}</span>
              {filled.map((field) => (
                <Badge key={field} variant="blue">
                  {field}
                </Badge>
              ))}
            </div>
          )}
          <p className="text-xs text-gray-600">{t("abha_confirm_form_hint")}</p>
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="self-start"
            onClick={() => setAccountOpen(true)}
          >
            {t("abha_card_and_qr")}
          </Button>
        </div>
      )}

      <AbhaVerifyDialog
        open={open}
        onOpenChange={setOpen}
        onAuthenticated={handleAuthenticated}
        facilityId={facilityId}
        initialIdentifier={
          isIndianMobile(phoneNumber)
            ? { type: "mobile", value: toIndianMobile(phoneNumber) }
            : undefined
        }
      />
      {session && (
        <AbhaAccountDialog
          open={accountOpen}
          onOpenChange={setAccountOpen}
          session={session}
          onProfileUpdated={setSession}
        />
      )}
    </section>
  );
}
