{"content": "import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { ShieldCheckIcon } from "lucide-react";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { toast } from "sonner";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";

import AbhaAccountDialog from "@/components/Abdm/AbhaAccountDialog";
import AbhaVerifyDialog from "@/components/Abdm/AbhaVerifyDialog";
import { getAbdmError, useAbdmConfig } from "@/components/Abdm/utils";

import { AbhaAuthenticatedResponse } from "@/types/abdm/abha";
import abhaApi from "@/types/abdm/abhaApi";
import { PatientRead } from "@/types/emr/patient/patient";
import mutate from "@/Utils/request/mutate";
import query from "@/Utils/request/query";

interface PatientAbhaSectionProps {
  patient: PatientRead;
  facilityId?: string;
  canWrite: boolean;
}

export default function PatientAbhaSection({
  patient,
  facilityId,
  canWrite,
}: PatientAbhaSectionProps) {
  const { t } = useTranslation();
  const queryClient = useQueryClient();
  const { enabled } = useAbdmConfig();
  const [verifyOpen, setVerifyOpen] = useState(false);
  const [session, setSession] = useState<AbhaAuthenticatedResponse | null>(null);

  const queryKey = ["abdm", "patient", patient.id];
  const { data: abha, isLoading } = useQuery({
    queryKey,
    // 404 here only means no ABHA is linked yet.
    queryFn: query(abhaApi.patient, {
      queryParams: { patient: patient.id },
      silent: true,
    }),
    enabled,
    retry: false,
  });

  const { mutate: link } = useMutation({
    mutationFn: mutate(abhaApi.link, { silent: true }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey });
    },
    onError: (e) => toast.error(getAbdmError(e, t("abha_link_failed")).message),
  });

  if (!enabled || isLoading) {
    return null;
  }

  const handleAuthenticated = (result: AbhaAuthenticatedResponse) => {
    // Linking again refreshes the stored profile snapshot for the same ABHA.
    if (canWrite && (!abha || abha.abha_number === result.profile.abha_number)) {
      link(
        { flow_id: result.flow_id, patient: patient.id },
        {
          onSuccess: () => {
            if (abha) setSession(result);
            else toast.success(t("abha_linked"));
          },
        },
      );
      return;
    }
    if (abha && abha.abha_number !== result.profile.abha_number) {
      toast.error(t("abha_verified_different_account"));
      return;
    }
    setSession(result);
  };

  return (
    <div className="mt-4 rounded-md border border-blue-400 bg-blue-50 p-5 flex flex-col gap-3">
      <div className="flex items-center justify-between gap-2">
        <h2 className="font-semibold flex items-center gap-2">
          <ShieldCheckIcon className="size-5 text-primary-700" />
          {t("abha")}
        </h2>
        {abha ? (
          <Button variant="outline" size="sm" onClick={() => setVerifyOpen(true)}>
            {t("abha_card_and_qr")}
          </Button>
        ) : (
          canWrite && (
            <Button variant="outline" size="sm" onClick={() => setVerifyOpen(true)}>
              {t("abha_link")}
            </Button>
          )
        )}
      </div>

      {abha ? (
        <dl className="grid grid-cols-1 gap-x-4 gap-y-2 md:grid-cols-2">
          <div>
            <dt className="text-sm text-gray-600">{t("abha_number")}</dt>
            <dd className="text-sm font-semibold font-mono">{abha.abha_number}</dd>
          </div>
          <div>
            <dt className="text-sm text-gray-600">{t("abha_address")}</dt>
            <dd className="text-sm font-semibold font-mono">
              {abha.abha_address || "-"}
            </dd>
          </div>
          <div className="md:col-span-2 flex gap-2">
            {abha.kyc_verified && <Badge variant="green">{t("abha_kyc_verified")}</Badge>}
            {abha.status && <Badge variant="secondary">{abha.status}</Badge>}
          </div>
        </dl>
      ) : (
        <p className="text-sm text-gray-700">{t("abha_not_linked")}</p>
      )}

      <AbhaVerifyDialog
        open={verifyOpen}
        onOpenChange={setVerifyOpen}
        onAuthenticated={handleAuthenticated}
        facilityId={facilityId}
        title={abha ? t("abha_verify_to_open") : t("abha_link")}
        initialIdentifier={
          abha ? { type: "abha_number", value: abha.abha_number, locked: true } : undefined
        }
        allowCreate={!abha}
      />
      {session && (
        <AbhaAccountDialog
          open={!!session}
          onOpenChange={(open) => !open && setSession(null)}
          session={session}
          onProfileUpdated={() => queryClient.invalidateQueries({ queryKey })}
        />
      )}
    </div>
  );
}
