/** UIDAI's published Aadhaar format: 12 digits, not starting 0 or 1, Verhoeff checksum. */
export function isValidAadhaar(value: string) {
  const digits = value.replace(/\D/g, "");
  if (!/^[2-9]\d{11}$/.test(digits)) return false;
  let check = 0;
  digits
    .split("")
    .reverse()
    .forEach((digit, i) => {
      check = VERHOEFF_D[check][VERHOEFF_P[i % 8][Number(digit)]];
    });
  return check === 0;
